INSERT INTO collection_pages VALUES('72a0b6bbd7b2cd0c130d07bd77b295dadfe05eeddec37c5c7703f4eb9aa8c18e','53fd6cc08b2510feee6ace3b0945add1f9e59e9c8561961f674c50451f3f0f7d','{"hasNext":false,"items":[{"author":{"account":{"login":"deepbratt","providerType":"User"},"email":"deepbratt@gmail.com","name":"Shuvradeb M"},"authoredDate":"2026-10-02T20:09:17Z","committedDate":"2026-10-02T20:09:17Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T18:06:49.075Z","repositoryId":622614210,"sha":"5e5e5b10a77d13ca4a79e646a87858165e1fa48f"}],"observedAt":"2026-10-08T18:06:49.075Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/13186668?v=4","events_url":"https://api.github.com/users/deepbratt/events{/privacy}","followers_url":"https://api.github.com/users/deepbratt/followers","following_url":"https://api.github.com/users/deepbratt/following{/other_user}","gists_url":"https://api.github.com/users/deepbratt/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/deepbratt","id":13186668,"login":"deepbratt","node_id":"MDQ6VXNlcjEzMTg2NjY4","organizations_url":"https://api.github.com/users/deepbratt/orgs","received_events_url":"https://api.github.com/users/deepbratt/received_events","repos_url":"https://api.github.com/users/deepbratt/repos","site_admin":false,"starred_url":"https://api.github.com/users/deepbratt/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/deepbratt/subscriptions","type":"User","url":"https://api.github.com/users/deepbratt","user_view_type":"public"},"comments_url":"https://api.github.com/repos/deepbratt/deepbratt/commits/5e5e5b10a77d13ca4a79e646a87858165e1fa48f/comments","commit":{"author":{"date":"2026-10-02T20:09:17Z","email":"deepbratt@gmail.com","name":"Shuvradeb M"},"comment_count":0,"committer":{"date":"2026-10-02T20:09:17Z","email":"noreply@github.com","name":"GitHub"},"message":"Rewrite profile README for current AI work (#1)\n\n* Rewrite the profile README around current work\n\nReplace the 2023 template with a profile grounded in the resume: Volvo and earlier roles, SnipInvoice, and Parezen in development. Drop dead stats widgets, hotlinked GIFs, and skills that are not on the resume.\n\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>\n\n* Keep contact badges on one line\n\nGitHub treats a badge image on its own line as a block, which stacked LinkedIn, GitHub, and Gmail. Put them in a single paragraph so they render as one row.\n\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>\n\n* Refresh profile stats and drop product names\n\nRemove the product section and name SnipInvoice and Parezen nowhere. Keep the AI line general. Replace the single stats card with widgets that returned a real image, plus a contribution snake generated with the default token.\n\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>\n\n---------\n\nCo-authored-by: Cursor Agent <cursoragent@cursor.com>\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>","tree":{"sha":"e3c31dfc529f0191ce9c2fdc24b905ce9b7825dd","url":"https://api.github.com/repos/deepbratt/deepbratt/git/trees/e3c31dfc529f0191ce9c2fdc24b905ce9b7825dd"},"url":"https://api.github.com/repos/deepbratt/deepbratt/git/commits/5e5e5b10a77d13ca4a79e646a87858165e1fa48f","verification":{"payload":"tree e3c31dfc529f0191ce9c2fdc24b905ce9b7825dd\nparent b2548b506e74bd9f41f502f3b24d2ede6c4c8e51\nauthor Shuvradeb M <deepbratt@gmail.com> 1790971757 +0530\ncommitter GitHub <noreply@github.com> 1790971757 +0530\n\nRewrite profile README for current AI work (#1)\n\n* Rewrite the profile README around current work\n\nReplace the 2023 template with a profile grounded in the resume: Volvo and earlier roles, SnipInvoice, and Parezen in development. Drop dead stats widgets, hotlinked GIFs, and skills that are not on the resume.\n\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>\n\n* Keep contact badges on one line\n\nGitHub treats a badge image on its own line as a block, which stacked LinkedIn, GitHub, and Gmail. Put them in a single paragraph so they render as one row.\n\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>\n\n* Refresh profile stats and drop product names\n\nRemove the product section and name SnipInvoice and Parezen nowhere. Keep the AI line general. Replace the single stats card with widgets that returned a real image, plus a contribution snake generated with the default token.\n\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>\n\n---------\n\nCo-authored-by: Cursor Agent <cursoragent@cursor.com>\nCo-authored-by: Shuvradeb M <deepbratt@users.noreply.github.com>","reason":"valid","signature":"-----BEGIN PGP SIGNATURE-----\n\nwsFcBAABCAAQBQJqwA9tCRC1aQ7uu5UhlAAAumUQAJs40PhzsE2+US79ulhB1lK9\n19EbeJU5ArjWlxAA8eSO6XmSj3Ftj+49aOvknGlKKya916rgIa6IdxWkBrGxPNV/\na91zmYqCohfxGTwfrXmQ9Ge8mA6MMlP+3siMIS0jFyuHnG0zic8aQgmRMsgY3OcR\n9oGfAKIfgtnyBeckTwaRt4ZUczzhjjhK+fR2kmlomgDA1waqZ7NUTnBKqTBlmDvc\n/8iFa/IElXeMByMPtdd8UF4+67hP65QVDSpH03DDHvGWfGrlrxGZe+eDiueQ1/sx\ninx7I/UJwv9LxYW2IN0Pc0VrUHcPNkDzmzg9Az/ksSB3Up5xUgl3Q/LyzDMGe0Pd\nPSysrLhIAi2CLysRAZw4+6+ufmdStx4vU0aWMwuNbECXh+w1asLfwEnqy0oDzSqd\nJ0V9fQjMRvDqgyLwrnSEf+cYI3kK/IzpF6JBOueHjS+EtZ9v3kW51MwxvkMp5bqf\njrIHk+VqL934E8PkS2v1jB3EIYFob/dBuHTqwWUDIDVdQPPrcT5cteKH+hXlmNyB\nhkpLoTrSp8t5Swh0LPTBTCxFwLVxFM8JmTSnOZmH7yXt/cyvSQ8+1ZMW0PySDvpe\nkMV62M38uE4lYTy46PA42XHWM5gUGiODCN7x3itICDL/ZKxO/2UOBGFPsZzr5p67\noqShivGC1ht1UFN3fkO4\n=Y+xg\n-----END PGP SIGNATURE-----\n","verified":true,"verified_at":"2026-10-02T20:09:18Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/19864447?v=4","events_url":"https://api.github.com/users/web-flow/events{/privacy}","followers_url":"https://api.github.com/users/web-flow/followers","following_url":"https://api.github.com/users/web-flow/following{/other_user}","gists_url":"https://api.github.com/users/web-flow/gists